# owner: platform
from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students given")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def _cells(student: Student) -> tuple:
    return (student.display_name, student.section, student.email)


def _line(cells: tuple, widths: List[int]) -> str:
    pairs = zip(cells, widths)
    return "  ".join(c.ljust(w) for c, w in pairs).rstrip()


# ---
def format_contacts(students: List[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by name."""
    _check(students)
    ordered = sorted(students, key=lambda item: item.display_name)
    rows = [_cells(item) for item in ordered]
    widths = [max(map(len, column)) for column in zip(*rows)]
    return [_line(cells, widths) for cells in rows]
EOF
