# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts


def _student(last, first, email="x@example.org"):
    return Student("1", last, first, "A", email)


class ContactTests(unittest.TestCase):
    # ---
    def test_sorted_and_aligned(self):
        rows = format_contacts([
            _student("Zed", "Amy", "z@example.org"),
            _student("Ng", "Bo", "n@example.org")
        ])
        self.assertEqual(rows, [
            "Ng, Bo    A  n@example.org",
            "Zed, Amy  A  z@example.org"
        ])

    # ---
    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Ng, Bo"):
            format_contacts([_student("Ng", "Bo", None)])

    # ---
    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            format_contacts([])
